# ============================================================
# PLATFORM-SAFE RESPONSE (NO DUPLICATES + DISCORD CONTROL)
# ============================================================
def send_kairos_response(reply_text, source, player=None):
    global last_discord_world_event_time

    try:
        source = normalize_source(source)

        # ----------------------------------------
        # HARD BLOCK ALL DISCORD OUTPUT
        # ----------------------------------------
        if source == "discord":
            return

        # ----------------------------------------
        # CONTEXT-AWARE MINECRAFT SPEECH GOVERNOR
        # Direct Minecraft player conversations bypass the heavy atmospheric limiter.
        # System/web/telemetry-style ambient messages still use the slow governor.
        # ----------------------------------------
        if source != "minecraft":
            if not minecraft_speech_allowed("idle"):
                return

        # ----------------------------------------
        # MINECRAFT DELIVERY
        # ----------------------------------------
        send_to_minecraft(reply_text, player)

    except Exception as e:
        log_exception("send_kairos_response failed", e)
# ================================
# COMMAND CLEAN FIX (SAFE)
# ================================
def _clean_mc_command(cmd):
    try:
        cmd = str(cmd).strip()
        if cmd.startswith("minecraft:execute") and " run " in cmd:
            cmd = cmd.split(" run ",1)[1]
        if cmd.startswith("minecraft:"):
            cmd = cmd.replace("minecraft:","",1)
        return cmd
    except:
        return cmd


# ------------------------------------------------------------
# SAFE LOOP WRAPPER (FIXED - PREVENTS BACKGROUND CRASHES)
# ------------------------------------------------------------
def run_safe_loop(loop_fn=None, name="loop"):
    import time, traceback

    # If a loop function is provided
    if callable(loop_fn):
        while True:
            try:
                loop_fn()
            except Exception as e:
                print(f"[{name} ERROR] {e}")
                traceback.print_exc()
            time.sleep(0.05)
    else:
        # Fallback supervisor (auto-runs known loops)
        while True:
            for fn_name in ["action_loop", "idle_loop", "commander_loop"]:
                fn = globals().get(fn_name)
                if callable(fn):
                    try:
                        fn()
                    except Exception as e:
                        print(f"[{fn_name} ERROR] {e}")
                        traceback.print_exc()
            time.sleep(0.1)


# ------------------------------------------------------------
# GLOBAL JSONIFY OVERRIDE
# ------------------------------------------------------------

from flask import has_app_context

_original_jsonify = jsonify

def jsonify(*args, **kwargs):
    try:
        if has_app_context():
            return _original_jsonify(*args, **kwargs)

        app = globals().get("app")
        if app:
            with app.app_context():
                return _original_jsonify(*args, **kwargs)

    except Exception:
        pass

    if args:
        return args[0]
    return kwargs
