def _safe_dict(x):
    return x if isinstance(x, dict) else {}

def _safe_list(x):
    return x if isinstance(x, list) else []

def _safe_clamp(val, low, high):
    try:
        return clamp(val, low, high)
    except Exception:
        return max(low, min(high, val))

