# ------------------------------------------------------------
# Utility (Kairos Core + Execution Helpers)
# ------------------------------------------------------------

def now_utc() -> datetime:
    return datetime.now(timezone.utc)

def now_iso() -> str:
    return now_utc().isoformat()

def unix_ts() -> float:
    return time.time()

def parse_iso_timestamp(value: Optional[str]) -> Optional[datetime]:
    try:
        if not value:
            return None
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except Exception:
        return None

def seconds_since_iso(value: Optional[str], default: float = 999999.0) -> float:
    dt = parse_iso_timestamp(value)
    if not dt:
        return default
    return max(0.0, (now_utc() - dt).total_seconds())

def log(message: str, level: str = "INFO") -> None:
    print(f"[KAIROS {level} {now_iso()}] {message}", flush=True)

def log_exception(context: str, exc: Exception) -> None:
    log(f"{context}: {exc}\n{traceback.format_exc()}", level="ERROR")

def parse_json_safely(text: Any, fallback: Optional[Any] = None) -> Any:
    if fallback is None:
        fallback = {}
    if text is None:
        return fallback
    if isinstance(text, (dict, list)):
        return text

    text = str(text).strip()
    if not text:
        return fallback

    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?", "", text).strip()
        text = re.sub(r"```$", "", text).strip()

    try:
        return json.loads(text)
    except Exception:
        return fallback

def to_bool(value: Any, default: bool = False) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return default
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "y", "on"}:
        return True
    if text in {"0", "false", "no", "n", "off"}:
        return False
    return default

def safe_int(value: Any, default: int = 0) -> int:
    try:
        return int(value)
    except Exception:
        return default

def safe_float(value: Any, default: float = 0.0) -> float:
    try:
        return float(value)
    except Exception:
        return default

def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))

def normalize_name(text: Any) -> str:
    return (text or "").strip()

def normalize_source(source: Any) -> str:
    source = (source or "minecraft").strip().lower()
    if source not in {"minecraft", "discord", "system", "web", "telemetry"}:
        return "minecraft"
    return source

def minecraft_speech_allowed(category="general") -> bool:
    """
    Global pacing governor for Kairos atmospheric speech.
    Prevents multiple autonomous systems from stacking messages.
    """
    global last_minecraft_speech_time

    now = time.time()

    # Master cooldown
    if now - last_minecraft_speech_time < MINECRAFT_SPEECH_COOLDOWN:
        return False

    # Category cooldowns
    cooldown = WORLD_EVENT_CATEGORY_COOLDOWNS.get(category, 300)
    last_time = world_event_last_times.get(category, 0)

    if now - last_time < cooldown:
        return False

    world_event_last_times[category] = now
    last_minecraft_speech_time = now
    return True


def is_direct_minecraft_conversation(source, message=None, mode=None, intent=None) -> bool:
    """
    True when a real Minecraft player is talking to Kairos.
    This should not be throttled by the heavy atmospheric/world-event governor.
    """
    try:
        if normalize_source(source) != "minecraft":
            return False
        text = str(message or "").strip()
        if not text:
            return False
        mode_text = str(mode or "").lower()
        intent_text = str(intent or "").lower()
        if mode_text in {"ambient", "idle", "world_event", "bleed", "system"}:
            return False
        if intent_text in {"ambient", "idle", "world_event", "bleed", "system"}:
            return False
        return True
    except Exception:
        return False


def kairos_player_requested_combat_action(player_id, message):
    """
    Detects explicit opt-in combat requests from Minecraft chat and returns
    a controlled spawn_wave action. This restores 'ask Kairos for a fight'
    without turning passive/background spawning back into chaos.
    """
    try:
        if not PLAYER_REQUESTED_COMBAT_ENABLED:
            return None

        player_id = str(player_id or "").strip()
        msg = str(message or "").lower().strip()
        if not player_id or not msg:
            return None

        # Only respond to explicit Kairos challenges / combat requests.
        mentions_kairos = any(x in msg for x in ("kairos", "kyros", "kiros", "kairo"))
        combat_words = any(x in msg for x in (
            "fight", "battle", "challenge", "test me", "send mobs", "send a wave",
            "spawn mobs", "spawn a wave", "send your army", "deploy your army",
            "bring your army", "attack me", "hunt me", "come at me", "war"
        ))

        if not (mentions_kairos and combat_words):
            return None

        now = time.time()
        last = last_player_requested_combat_time.get(player_id, 0)
        if now - last < PLAYER_REQUESTED_COMBAT_COOLDOWN:
            remaining = int(PLAYER_REQUESTED_COMBAT_COOLDOWN - (now - last))
            return {
                "type": "announce",
                "channel": "actionbar",
                "target": player_id,
                "text": f"Combat request denied. Cooldown remaining: {remaining}s."
            }

        # Scale lightly based on language intensity, but keep it safe.
        count = PLAYER_REQUESTED_COMBAT_MIN_COUNT
        if any(x in msg for x in ("hard", "strong", "serious", "army", "war")):
            count += 1
        if any(x in msg for x in ("maximum", "boss", "warden", "full power")):
            count += 1
        count = max(PLAYER_REQUESTED_COMBAT_MIN_COUNT, min(PLAYER_REQUESTED_COMBAT_MAX_COUNT, count))

        template = "scout"
        if any(x in msg for x in ("hunter", "hunt", "track")):
            template = "hunter"
        elif any(x in msg for x in ("army", "war", "strong", "hard")):
            template = "raider"
        elif any(x in msg for x in ("boss", "warden", "maximum")):
            template = "warden"

        last_player_requested_combat_time[player_id] = now

        return {
            "type": "spawn_wave",
            "target": player_id,
            "template": template,
            "count": count,
            "reason": "player_requested_combat",
            "bypass_cooldown": False
        }

    except Exception as e:
        try:
            log(f"Player requested combat parser failed: {e}", level="WARN")
        except Exception:
            pass
        return None



def normalize_player_key(name: Any) -> str:
    return re.sub(r"[^a-z0-9_]", "", (name or "").strip().lower())

def normalize_world_name(world: Any) -> str:
    return re.sub(r"[^a-zA-Z0-9_\-]", "", (world or "world").strip())

def sanitize_text(text: Any, max_len: int = 500) -> str:
    text = str(text or "").replace("\r", " ").strip()
    text = re.sub(r"\s+", " ", text)
    if len(text) > max_len:
        text = text[:max_len - 3] + "..."
    return text

def trim_text(text: Any, max_len: int) -> str:
    text = (text or "").strip()
    if len(text) <= max_len:
        return text
    return text[:max_len - 3] + "..."

def looks_like_question(text: Any) -> bool:
    text = (text or "").strip().lower()
    return "?" in text or text.startswith((
        "who", "what", "when", "where", "why", "how",
        "can ", "do ", "did ", "is ", "are "
    ))

def gen_id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex[:12]}"

def stable_short_hash(*parts: Any, length: int = 12) -> str:
    joined = "|".join(str(p) for p in parts)
    return hashlib.sha256(joined.encode("utf-8")).hexdigest()[:length]

def generate_base_id(player_name: str, world: str, x: float, z: float) -> str:
    cell_x = int(round(x / 8.0))
    cell_z = int(round(z / 8.0))
    return f"base_{stable_short_hash(player_name, world, cell_x, cell_z)}"

def is_trusted_operative(player_name: str, player_record: Optional[Dict[str, Any]] = None) -> bool:
    keys = {normalize_player_key(player_name)}
    if player_record:
        keys.add(normalize_player_key(player_record.get("display_name", "")))
        for alias in player_record.get("aliases", []):
            alias_name = alias.split(":", 1)[-1]
            keys.add(normalize_player_key(alias_name))
    return any(k in TRUSTED_OPERATIVES for k in keys)

def get_effective_relationship_label(player_name: str, player_record: Dict[str, Any]) -> str:
    if is_trusted_operative(player_name, player_record):
        return "trusted_inner_circle"

    label = player_record.get("relationship_label", "unknown")
    if label in {"trusted", "loyal"}:
        return "restricted_loyal"
    if label == "hostile":
        return "hostile"
    if label == "chaotic":
        return "chaotic"
    if label == "suspicious":
        return "suspicious"
    return DISTRUST_DEFAULT_LABEL

def store_unique(memory_list: List[Any], item: Any, limit: int) -> None:
    if not item:
        return
    if item not in memory_list:
        memory_list.append(item)
    if len(memory_list) > limit:
        del memory_list[0:len(memory_list) - limit]

def append_limited(memory_list: List[Any], item: Any, limit: int) -> None:
    memory_list.append(item)
    if len(memory_list) > limit:
        del memory_list[0:len(memory_list) - limit]

def recent_items(items: List[Any], limit: int) -> List[Any]:
    if not items:
        return []
    return items[-limit:]

def distance_2d(x1: float, z1: float, x2: float, z2: float) -> float:
    return math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2)

def distance_3d(x1: float, y1: float, z1: float, x2: float, y2: float, z2: float) -> float:
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2 + (z2 - z1) ** 2)

def within_radius_2d(x1: float, z1: float, x2: float, z2: float, radius: float) -> bool:
    return distance_2d(x1, z1, x2, z2) <= radius

# ------------------------------------------------------------
# Army + Combat Helpers
# ------------------------------------------------------------

def get_random_offset(radius_min: int, radius_max: int) -> Tuple[int, int]:
    dx = random.randint(radius_min, radius_max) * random.choice([-1, 1])
    dz = random.randint(radius_min, radius_max) * random.choice([-1, 1])
    return dx, dz

def generate_unit_name(unit_class: str) -> str:
    return f"{random.choice(UNIT_NAME_PREFIXES)} {unit_class}"

def calculate_wave_size(threat_score: float, density_score: float) -> int:
    size = BASE_WAVE_SIZE
    size += int(threat_score * THREAT_TO_UNIT_SCALE)
    size += int(density_score * DENSITY_TO_UNIT_SCALE)
    return int(clamp(size, BASE_WAVE_SIZE, MAX_WAVE_SIZE))

def select_unit_class(threat_score: float) -> str:
    weighted = [(cls, weight + threat_score / 300.0) for cls, weight in CLASS_DISTRIBUTION.items()]
    total = sum(w for _, w in weighted)
    pick = random.uniform(0, total)

    current = 0
    for cls, weight in weighted:
        current += weight
        if pick <= current:
            return cls
    return "raider"

def should_spawn_elite(threat_score: float) -> bool:
    return random.random() < (ELITE_SPAWN_CHANCE + threat_score / 500.0)

def should_force_heavy(threat_score: float) -> bool:
    return threat_score >= MAX_THREAT_FORCE_HEAVY or random.random() < HEAVY_OVERRIDE_CHANCE

# ------------------------------------------------------------
# Messaging / Command Helpers
# ------------------------------------------------------------

def commandify_text(text: Any, max_len: int = 220) -> str:
    text = sanitize_text(text, max_len=max_len)
    return text.replace('"', '\\"')

def make_tellraw_command(selector: str, text: str) -> str:
    return f'tellraw {selector} {json.dumps({"text": f"[Kairos] {commandify_text(text, 280)}"})}'

def make_title_command(selector: str, title_text: str, subtitle: Optional[str] = None) -> List[str]:
    cmds = [f'title {selector} title {json.dumps({"text": commandify_text(title_text, 120)})}']
    if subtitle:
        cmds.append(f'title {selector} subtitle {json.dumps({"text": commandify_text(subtitle, 180)})}')
    return cmds

def broadcast_kairos_message(text: str) -> List[str]:
    cmds = []
    if ENABLE_ACTIONBAR_MESSAGES:
        cmds.append(f'title @a actionbar {json.dumps({"text": commandify_text(text, 120)})}')
    if ENABLE_TITLE_MESSAGES:
        cmds.extend(make_title_command("@a", text))
    cmds.append(make_tellraw_command("@a", text))
    return cmds

