    threat_delta = 0.0

    if label == "hostile":
        threat_delta += 10.0

    elif label == "unstable":
        threat_delta += 8.0

    elif label == "suspicious":
        threat_delta += 5.0

    elif label == "loyal":
        threat_delta -= 3.0

    # Apply trust modifiers
    threat_delta = apply_trait_to_threat(player_record, threat_delta)

    if threat_delta != 0:
        update_threat(player_id, threat_delta, reason=f"relationship:{label}")


