# Mission Progress Update
# ------------------------------------------------------------

def update_mission_progress(memory_data, mission_id, note):
    mission = memory_data["active_missions"].get(mission_id)
    if not mission:
        return

    append_limited(
        mission["progress"],
        {
            "timestamp": now_iso(),
            "note": trim_text(note, 200)
        },
        MAX_MISSION_PROGRESS
    )

    mission["updated_at"] = now_iso()


