NPC_REGISTRY = {
    "382": {
        "name": "Trojan Guard",
        "role": "guard",
        "faction": "trojan",
        "personality": "fearful"
    }
}

@app.route("/npc_chat", methods=["POST"])
def npc_chat():

    try:
        data = request.json or {}

        player = str(data.get("player", "Unknown"))
        npc_id = str(data.get("npc_id", "0"))

        npc = NPC_REGISTRY.get(npc_id)

        if not npc:
            return jsonify({
                "ok": False,
                "error": "unknown_npc"
            })

        system_prompt = f"""
You are {npc['name']} inside the Nexus universe.

Faction: {npc['faction']}
Role: {npc['role']}
Personality: {npc['personality']}

You are speaking directly to player {player}.

Rules:
- Stay immersive.
- Keep replies under 2 sentences.
- Speak like a living MMORPG NPC.
- Never mention being AI.
- Never break character.
"""

        if not client:
            reply = "The guard watches you silently."
        else:
            response = client.chat.completions.create(
                model=MODEL_NAME,
                messages=[
                    {"role": "system", "content": system_prompt}
                ]
            )

            reply = (
                response.choices[0]
                .message
                .content
                .strip()
            )

        send_to_minecraft(
            f"[{npc['name']}] {reply}",
            player
        )

        return jsonify({
            "ok": True,
            "reply": reply
        })

    except Exception as e:
        log_exception("npc_chat failed", e)
        return jsonify({
            "ok": False,
            "error": str(e)
        })


