    data = kw_reputation()

    rep = data.setdefault("players", {}).setdefault(player, {})

    rep[faction] = max(
        -100,
        min(100, int(rep.get(faction, 0)) + int(amount))
    )

    rep["updated_at"] = now_iso()

    kw_save_reputation(data)

    return {"ok": True, "reputation": rep}

