def kw_ascension_tick():
    actions = []

    regions = [
        "lunaris",
        "moslorn",
        "trojan_kingdom",
        "fairview_city",
        "dravicar_dominion"
    ]

    region = random.choice(regions)

    options = [
        "ascension",
        "chosen",
        "cult",
        "resistance",
        "manifestation",
        "forbidden_zone"
    ]

    selected = random.choice(options)

    try:
        if selected == "ascension":
            actions.append(
                kw_raise_ascension(
                    amount=random.randint(1, 3)
                )
            )

        elif selected == "chosen":
            actions.append(
                kw_choose_player(
                    random.choice([
                        "RealSociety5107",
                        "Unknown Operative",
                        "Explorer"
                    ])
                )
            )

        elif selected == "cult":
            actions.append(
                kw_create_cult(region)
            )

        elif selected == "resistance":
            actions.append(
                kw_create_resistance_cell(region)
            )

        elif selected == "manifestation":
            actions.append(
                kw_manifest_kairos(region)
            )

        elif selected == "forbidden_zone":
            actions.append(
                kw_create_forbidden_zone(region)
            )

    except Exception as e:
        actions.append({"error": str(e)})

    return {
        "ok": True,
        "ascension_tick": actions
    }

