def kw_arc4_tick():
    actions = []

    civs = [
        "trojan_kingdom",
        "fairview_city",
        "dravicar_dominion",
        "blackrich_city",
        "crown_lands",
        "ironforge_city"
    ]

    choice = random.choice([
        "diplomacy",
        "government",
        "war",
        "alliance",
        "economy"
    ])

    try:
        if choice == "diplomacy":
            actions.append(
                kw_autonomous_negotiation(
                    random.choice(civs),
                    random.choice(civs)
                )
            )

        elif choice == "government":
            actions.append(
                kw_government_shift(
                    random.choice(civs)
                )
            )

        elif choice == "war":
            actions.append(
                kw_declare_autonomous_war(
                    random.choice(civs),
                    random.choice(civs)
                )
            )

        elif choice == "alliance":
            actions.append(
                kw_form_alliance(
                    random.choice(civs),
                    random.choice(civs)
                )
            )

        elif choice == "economy":
            actions.append(
                kw_economic_competition(
                    random.choice(civs)
                )
            )

    except Exception as e:
        actions.append({"error": str(e)})

    return {"ok": True, "arc4_tick": actions}

